vec4 Effect(vec2 uv) {
// Scale UV coordinates to complex plane (-2 to 2)
vec2 c = (uv - 0.5) * 2.5;

vec2 z = vec2(0.0);
float iterations = 10.0;

for(float i = 0.0; i < iterations; i++) {
// Compute z^2 + c
vec2 zSquared = vec2(
z.x*z.x - z.y*z.y,
2.0 * z.x * z.y
);

z = zSquared + c;

// Check for divergence
if(length(z) > 4.0) break;
}

// Color based on how much it diverged
float colorIntensity = length(z) / 4.0;
vec3 color = mix(
vec3(0.0),
vec3(0.1, 0.8, 1.0) * sin(iTime + 2.0) * 0.5 + 0.5,
colorIntensity
);

return vec4(color, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = Effect(uv).rgb;//0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = vec4(col,1.0);
}
